let results = [];

// items는 앞 노드에서 넘겨받은 전체 페이지(1페이지, 2페이지, 3페이지...)야.
// for문을 써서 페이지 수만큼 반복해서 데이터를 빼내는 작업을 할 거야.
for (let item of items) {
  const input = item.json;

  const titles = input.title || [];
  const urls = input.url || [];
  const dates = (input.date || []).filter(d => /\d{4}[-.]\d{2}[-.]\d{2}/.test(d));

  // 각 페이지당 추출된 데이터 수만큼 루프를 돌며 짝을 맞춘다.
  // 이제 딱 10개씩 들어오기 때문에 listCount로 강제로 자를 필요가 없어졌어.
  for (let i = 0; i < titles.length; i++) {
    results.push({
      json: {
        title: titles[i].replace(/\n/g, "").trim(), // 줄바꿈 제거
        url: urls[i],
        date: dates[i].replace(/\./g, "-") // 날짜 형식을 YYYY-MM-DD로 통일
      }
    });
  }
}

return results;

const allData = $input.all();
if (allData.length === 0) return [];

return allData.map(item => {
  // 1. 데이터 가져오기
  const contentList = item.json["질의내역"] || item.json["text"] || ""; 
  let rawText = Array.isArray(contentList) ? contentList.join("\n") : contentList;
  let text = rawText.trim();

  let extractedTitle = "제목 없음";
  let classification = "구분 없음";
  let actualTitle = "제목 없음";
  let inquiryDate = "날짜 없음"; // '질의 작성일'을 담을 변수

  if (text) {
    const lines = text.split('\n');

    // --- 질의 작성일 추출 로직 ---
    // 텍스트 내에서 '작성일 0000.00.00' 형태를 찾아 날짜만 가져옴
    const dateMatch = text.match(/작성일\s*(\d{4}\.\d{2}\.\d{2})/);
    if (dateMatch) {
      inquiryDate = dateMatch[1]; 
    }

    extractedTitle = lines[0].trim();

    // 2. 제목 추출 및 '구분'과 '제목'으로 분리
    const titleMatch = extractedTitle.match(/^(\S+회계(?:\[[^\]]+\])?)\s+(.*)/);
    if (titleMatch) {
      classification = titleMatch[1].trim();
      actualTitle = titleMatch[2].trim();
    } else {
      actualTitle = extractedTitle;
    }
  }

  // [필터링 조건]: '교비' 또는 '법인'이 포함되지 않으면 제외
  if (!classification.includes("교비") && !classification.includes("법인")) {
    return null;
  }

  // --- 항목별 추출 함수 ---
  function extractSection(targetText, startPattern, endPattern) {
    const startMatch = targetText.match(startPattern);
    if (!startMatch) return "내용 없음";
    let startIndex = startMatch.index + startMatch[0].length;
    let sectionText = targetText.substring(startIndex).replace(/^[\s:]+/, '');
    let endIndex = sectionText.length;
    if (endPattern) {
      const endMatch = sectionText.match(endPattern);
      if (endMatch) endIndex = endMatch.index;
    }
    const result = sectionText.substring(0, endIndex).trim();
    return result === "" ? "내용 없음" : result;
  }

  let fact = extractSection(text, /1\.\s*사실관계/, /2\.\s*질의사항/);
  let question = extractSection(text, /2\.\s*질의사항/, /3\.\s*(관련|관계)법령/);
  const law = extractSection(text, /3\.\s*(관련|관계)법령/, /첨부파일/);

  // 사실관계/질의사항이 비어있을 경우 예외 처리
  if (fact === "내용 없음" && question === "내용 없음") {
    let bodyText = text.substring(extractedTitle.length);
    const lawMatch = bodyText.match(/3\.\s*(관련|관계)법령/);
    const attachMatch = bodyText.match(/첨부파일/);
    let cutIndex = bodyText.length;
    if (lawMatch) cutIndex = lawMatch.index;
    else if (attachMatch) cutIndex = attachMatch.index;

    bodyText = bodyText.substring(0, cutIndex);
    const cleanedLines = bodyText.split('\n').filter(line => {
      const trimmed = line.trim();
      if (trimmed === "") return false;
      if (trimmed.match(/^작성일\s*\d{4}\.\d{2}\.\d{2}/)) return false;
      if (trimmed.match(/^※/)) return false;
      return true;
    });
    question = cleanedLines.join('\n').trim() || "내용 없음";
  }

  // 최종 결과 반환 (질의 작성일을 가장 위로 배치)
  return {
    json: {
      content: {
        "질의 작성일": inquiryDate, // 명칭 변경 완료
        "구분": classification,
        "제목": actualTitle,
        "1.사실관계": fact,
        "2.질의사항": question,
        "3.관련법령": law
      }
    }
  };
}).filter(item => item !== null);

const maxPages = 3; // 크롤링할 최대 페이지 수 (원하는 만큼 숫자 수정)
const results = [];

for (let i = 1; i <= maxPages; i++) {
  results.push({ json: { pageNo: i } });
}

return results;

return items.map(item => {
  const data = item.json;
  const inputText = data.output || ""; 

  // 추출 시 앞부분의 콜론(:)과 공백을 제거하는 헬퍼 함수
  const cleanText = (text) => {
    return text ? text.trim().replace(/^[:\s\n\r]+/, "").trim() : "";
  };

  // 1. 헤더 정보 추출
  const dateMatch = inputText.match(/질의\s*작성일\s*:\s*([\d.]+)/);
  const headerPart = inputText.split("제목")[0]; 
  const categoryMatch = headerPart.match(/구분\s*:\s*([^\n\r]+)/);
  const titleRegex = /제목\s*:\s*(.*)/;

  // 2. 질의 내용 추출
  const questionContentRegex = /질의\s*내용\s*:\s*([\s\S]*?)(?=1\.\s*질의\s*요약|$)/;

  // 3. 나머지 항목들 추출
  const summaryRegex = /1\.\s*질의\s*요약\s*([\s\S]*?)(?=2\.\s*답변|$)/;
  const answerRegex = /2\.\s*답변\s*([\s\S]*?)(?=3\.\s*관련 법령|$)/;
  const lawsRegex = /3\.\s*관련 법령\s*([\s\S]*?)(?=4\.\s*유사 사례|$)/;
  const casesRegex = /4\.\s*유사 사례\s*([\s\S]*)/;

  // 값 할당 및 정제 (cleanText 적용)
  const date = dateMatch ? dateMatch[1].trim() : "미지정";
  const category = categoryMatch ? categoryMatch[1].trim() : "미지정";
  const title = (inputText.match(titleRegex)?.[1] || "").trim();
  const questionContent = cleanText(inputText.match(questionContentRegex)?.[1]);

  const summary = cleanText(inputText.match(summaryRegex)?.[1]);
  const answer = cleanText(inputText.match(answerRegex)?.[1]);
  const laws = cleanText(inputText.match(lawsRegex)?.[1]);
  const cases = cleanText(inputText.match(casesRegex)?.[1]);

  // 컨텐츠 병합 (내용이 있는 것만)
  const combinedContent = [
    summary ? `[질문 요약]\n${summary}` : "",
    answer ? `[답변]\n${answer}` : "",
    laws ? `[관련 법령]\n${laws}` : "",
    cases ? `[유사 사례]\n${cases}` : ""
  ].filter(text => text !== "").join('\n\n');

  return {
    json: {
      "구분": category,
      "질의작성일": date,
      "제목": title,
      "질의내용": questionContent,
      "컨텐츠": combinedContent
    }
  };
});

const extracted = typeof $json.output === 'string'
  ? JSON.parse($json.output)
  : ($json.output ?? $json);
const question = extracted.question ?? {};
const asText = (value) => typeof value === 'string' ? value.trim() : '';
const normalize = (value, maxLength) => [...new Set(
  (Array.isArray(value) ? value : []).map(asText).filter(Boolean)
)].slice(0, maxLength);
const questionText = [
  ['제목', asText(question['제목'])],
  ['사실관계', asText(question['1.사실관계'])],
  ['질의사항', asText(question['2.질의사항'])],
  ['관련법령', asText(question['3.관련법령'])],
].filter(([, value]) => value).map(([label, value]) => `${label}: ${value}`).join('\n');
if (!questionText) throw new Error('검색할 원문 질의가 없습니다.');
return [{ json: {
  question,
  core_keywords: normalize(extracted.core_keywords, 3),
  optional_keywords: normalize(extracted.optional_keywords, 6),
  question_text: questionText,
  match_count: 20,
  filter: {},
} }];

const prepared = $('Prepare Hybrid Search').item.json;
const embedding = $json.data?.[0]?.embedding;
if (!Array.isArray(embedding) || embedding.length !== 1536) {
  throw new Error('text-embedding-3-small 임베딩(1536차원)을 받지 못했습니다.');
}
return [{ json: { ...prepared, query_embedding: embedding } }];

const prepared = $('Prepare Hybrid Search').item.json;
const candidates = $input.all().flatMap((item) => {
  if (Array.isArray(item.json)) return item.json;
  if (Array.isArray(item.json.body)) return item.json.body;
  return item.json?.id ? [item.json] : [];
});
if (candidates.length === 0) {
  throw new Error('Supabase V3 검색 결과가 없습니다. RPC 입력과 필터를 확인하세요.');
}
return [{ json: {
  ...prepared,
  candidates,
  documents: candidates.map((row) => row.content ?? ''),
} }];

const search = $('Prepare Cohere Rerank').item.json;
const results = Array.isArray($json.results) ? $json.results : [];
const chunks = results.slice(0, 7).map(({ index, relevance_score }) => ({
  ...search.candidates[index],
  rerank_score: relevance_score,
})).filter((row) => row.id !== undefined);
return [{ json: {
  question: search.question,
  core_keywords: search.core_keywords,
  optional_keywords: search.optional_keywords,
  chunks,
} }];
